        return self.path.read_bytes()

    def rows(self):
        with self.path.open(newline="", encoding="utf-8") as f:
            return list(csv.reader(f))

    def test_d1_export_exits_zero_and_writes_the_file(self):
        self.export()
        self.assertTrue(self.path.is_file())

    def test_d2_first_row_is_the_header(self):
        content = self.export()
        self.assertEqual(content.split(b"\r\n")[0], b"id,customer,total,placed_on")

    def test_d3_every_order_once_in_list_order(self):
        self.export()
        ids = [int(row[0]) for row in self.rows()[1:]]
        self.assertEqual(ids, [order.id for order in load_orders()])

    def test_e1_customer_with_a_comma_stays_one_field(self):
        content = self.export()
        self.assertIn(b'"Berg, Hanna"', content)
        by_id = {row[0]: row for row in self.rows()[1:]}
